import{_ as t,o as i,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const d=JSON.parse('{"title":"Diverse Projekte","description":"","frontmatter":{},"headers":[],"relativePath":"projects-diverse/index.md","filePath":"projects-diverse/index.md","lastUpdated":1792857501000}'),n={name:"projects-diverse/index.md"};function l(s,e,o,u,p,h){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="diverse-projekte" tabindex="-1">Diverse Projekte <a class="header-anchor" href="#diverse-projekte" aria-label="Permalink to &quot;Diverse Projekte&quot;">​</a></h1><p>Diese Seite sammelt weitere UGSo-Open-Source-Projekte, die nicht direkt zu den C#-Werkzeugen oder MQTT-Apps gehören.</p><h2 id="ultimate-timer" tabindex="-1">Ultimate Timer <a class="header-anchor" href="#ultimate-timer" aria-label="Permalink to &quot;Ultimate Timer&quot;">​</a></h2><p><strong>Ultimate Timer</strong></p><p>Ein Home-Assistant-Automations-Blueprint für wiederverwendbare Timer mit stabiler STOP-Logik, dauerhaftem DONE-Status, Multi-Instance-Unterstützung und optionalem MQTT-Betrieb.</p><ul><li><a href="/projects/ultimate-timer/">Ultimate-Timer-Dokumentation öffnen</a></li><li><a href="https://github.com/rockbaer2007/ha-ultimate-timer-blueprint" target="_blank" rel="noreferrer">Blueprint auf GitHub öffnen</a></li></ul><h2 id="home-assistant-blueprints" tabindex="-1">Home Assistant Blueprints <a class="header-anchor" href="#home-assistant-blueprints" aria-label="Permalink to &quot;Home Assistant Blueprints&quot;">​</a></h2><p><strong>Home Assistant Blueprints</strong></p><p>Eine kleine Sammlung eigener Home-Assistant-Blueprints für Verknüpfungen, Zielgruppen und Not-Aus-Funktionen. Enthalten sind Blueprints für eine Quelle mit bis zu sechs Zielen, eine Quelle mit frei wählbarer Zielgruppe sowie eine Not-Aus-Automation, die beim Wechsel von <code>on</code> nach <code>off</code> ausgewählte Ziele ausschaltet.</p><ul><li><p>Verknüpfung 1 zu 6: Eine Quelle schaltet bis zu sechs Ziele synchron ein und aus.</p></li><li><p>Verknüpfung Quelle zu Zielgruppe: Eine Quelle schaltet frei ausgewählte Entitäten, Geräte oder Bereiche.</p></li><li><p>Not-Aus Quelle AUS zu Zielgruppe AUS: Beim Wechsel der Quelle von <code>on</code> nach <code>off</code> werden die ausgewählten Ziele ausgeschaltet.</p></li><li><p>Das GitHub-README enthält direkte Home-Assistant-Import-Buttons für alle enthaltenen Blueprints.</p></li><li><p><a href="https://github.com/rockbaer2007/homeassistant-blueprints" target="_blank" rel="noreferrer">Blueprints auf GitHub öffnen</a></p></li></ul><h2 id="weitere-projektbereiche" tabindex="-1">Weitere Projektbereiche <a class="header-anchor" href="#weitere-projektbereiche" aria-label="Permalink to &quot;Weitere Projektbereiche&quot;">​</a></h2><ul><li><a href="/projects/">C# Projekte öffnen</a></li><li><a href="/projects-mqtt/">MQTT Projekte öffnen</a></li><li><a href="/projects/atlas/">ATLAS öffnen</a></li></ul>',12)])])}const m=t(n,[["render",l]]);export{d as __pageData,m as default};
